 IF NOT ((SELECT COUNT(*) FROM (SELECT k.CONSTRAINT_NAME,k.COLUMN_NAME,k.ORDINAL_POSITION,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.UPDATE_RULE,r.DELETE_RULE,(k.REFERENCED_TABLE_SCHEMA=DATABASE()) REFERENCED_SCHEMA_IS_CURRENT FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME AND r.TABLE_NAME=k.TABLE_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='managed_payouts' AND k.REFERENCED_TABLE_NAME IS NOT NULL) hb_check_rows)=3 AND NOT EXISTS(SELECT 1 FROM (SELECT k.CONSTRAINT_NAME,k.COLUMN_NAME,k.ORDINAL_POSITION,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.UPDATE_RULE,r.DELETE_RULE,(k.REFERENCED_TABLE_SCHEMA=DATABASE()) REFERENCED_SCHEMA_IS_CURRENT FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME AND r.TABLE_NAME=k.TABLE_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='managed_payouts' AND k.REFERENCED_TABLE_NAME IS NOT NULL) hb_check_rows WHERE NOT ((BINARY `CONSTRAINT_NAME` <=> BINARY 'managed_payouts_approver_fk' AND BINARY `COLUMN_NAME` <=> BINARY 'approved_by' AND `ORDINAL_POSITION`=1 AND BINARY `REFERENCED_TABLE_NAME` <=> BINARY 'users' AND BINARY `REFERENCED_COLUMN_NAME` <=> BINARY 'id' AND BINARY `UPDATE_RULE` <=> BINARY 'RESTRICT' AND BINARY `DELETE_RULE` <=> BINARY 'NO ACTION' AND `REFERENCED_SCHEMA_IS_CURRENT`=1) OR (BINARY `CONSTRAINT_NAME` <=> BINARY 'managed_payouts_preparer_fk' AND BINARY `COLUMN_NAME` <=> BINARY 'prepared_by' AND `ORDINAL_POSITION`=1 AND BINARY `REFERENCED_TABLE_NAME` <=> BINARY 'users' AND BINARY `REFERENCED_COLUMN_NAME` <=> BINARY 'id' AND BINARY `UPDATE_RULE` <=> BINARY 'RESTRICT' AND BINARY `DELETE_RULE` <=> BINARY 'NO ACTION' AND `REFERENCED_SCHEMA_IS_CURRENT`=1) OR (BINARY `CONSTRAINT_NAME` <=> BINARY 'managed_payouts_seller_fk' AND BINARY `COLUMN_NAME` <=> 