 IF NOT ((SELECT COUNT(*) FROM (SELECT CONSTRAINT_NAME,CHECK_CLAUSE,LEVEL FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='managed_payouts' AND CONSTRAINT_NAME NOT IN ('hb_ck_managed_payouts_fa4bbd3eb6','hb_ck_managed_payouts_53a2c40e69','hb_ck_managed_payouts_a0abe9d440')) hb_check_rows)=2 AND NOT EXISTS(SELECT 1 FROM (SELECT CONSTRAINT_NAME,CHECK_CLAUSE,LEVEL FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='managed_payouts' AND CONSTRAINT_NAME NOT IN ('hb_ck_managed_payouts_fa4bbd3eb6','hb_ck_managed_payouts_53a2c40e69','hb_ck_managed_payouts_a0abe9d440')) hb_check_rows WHERE NOT ((BINARY `CONSTRAINT_NAME` <=> BINARY 'managed_payout_positive' AND BINARY `CHECK_CLAUSE` <=> BINARY '`amount_paisa` > 0' AND BINARY `LEVEL` <=> BINARY 'Table') OR (BINARY `CONSTRAINT_NAME` <=> BINARY 'record_kind' AND BINARY `CHECK_CLAUSE` <=> BINARY '`record_kind` in (''simulation'',''live'')' AND BINARY `LEVEL` <=> BINARY 'Column')))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='check_parity_managed_payouts_original_checks'; END IF;
 IF NOT ((SELECT COUNT(*) FROM (SELECT `TRIGGER_NAME`,`EVENT_MANIPULATION`,`EVENT_OBJECT_TABLE`,`ACTION_ORDER`,`ACTION_STATEMENT`,`ACTION_TIMING` FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='managed_payouts') hb_check_rows)=13 AND NOT EXISTS(SELECT 1 FROM (SELECT `TRIGGER_NAME`,`EVENT_MANIPULATION`,`EVENT_OBJECT_TABLE`,`ACTION_ORDER`,`ACTION_STATEMENT`,`ACTION_TIMING` FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='managed_payouts') hb_check_rows WHERE NOT ((BINARY `TRIGGER_NAME` <=> BINARY 'managed_actual_execution_packet' AND BINARY `EVENT_MANIPULATION` <=> BINARY 'UPDATE' AND BINARY `EVENT_OBJECT_TABLE` <=> BINARY 'managed_payouts' AND `ACTION_ORDER`=4 AND BINARY `ACTION_STATEMENT` <=> BINARY 'BEGIN IF (NEW.status<>OLD.status AND NEW.status IN(''processing'',''paid'',''failed'') AND NOT EXISTS(SELECT 1 FROM payout_transfer_packets p JOIN users u ON u.id=CASE WHEN NEW.status=''processing'' THEN p.started_by ELSE p.recorded_by END JOIN user_roles r ON r.user_id=u.id WHERE p.managed_payout_id=NEW.id AND p.seller_id=NEW.seller_id AND p.state=NEW.status AND p.amount_paisa=NEW.amount_paisa AND u.status=''active'' AND r.role=''super_admin'')) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''managed_payout_requires_actual_execution_packet''; END IF; END' AND BINARY `ACTION_TIMING` <=> BINARY 'BEFORE') OR (BINARY `TRIGGER_NAME` <=> BINARY 'managed_actual_live_instruction_retained' AND BINARY `EVENT_MANIPULATION` <=> BINARY 'UPDATE' AND BINARY `EVENT_OBJECT_TABLE` <=> BINARY 'managed_payouts' AND `ACTION_ORDER`=8 AND BINARY `ACTION_STATEMENT` <=> BINARY 'BEGIN IF (OLD.record_kind=''live'' AND NEW.status=''rejected'' AND OLD.status<>NEW.status AND EXISTS(SELECT 1 FROM payout_transfer_packets p WHERE p.managed_payout_id=NEW.id AND p.state NOT IN(''void'',''failed''))) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''retire_or_reconcile_original_payout_instruction_first''; END IF; END' AND BINARY `ACTION_TIMING` <=> BINARY 'BEFORE') OR (BINARY `TRIGGER_NAME` <=> BINARY 'managed_live_instruction_retained' AND BINARY `EVENT_MANIPULATION` <=> BINARY 'UPDATE' AND BINARY `EVENT_OBJECT_TABLE` <=> BINARY 'managed_payouts' AND `ACTION_ORDER`=5 AND BINARY `ACTION_STATEMENT` <=> BINARY 'BEGIN IF (NEW.status=''cancelled'' AND OLD.status<>NEW.status AND EXISTS(SELECT 1 FROM payout_transfer_packets p WHERE p.managed_payout_id=NEW.id AND p.state NOT IN(''void'',''failed''))) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''retire_or_reconcile_original_payout_instruction_first''; END IF; END' AND BINARY `ACTION_TIMING` <=> BINARY 'BEFORE') OR (BINARY `TRIGGER_NAME` <=> BINARY 'managed_live_payout_independent_actor' AND BINARY `EVENT_MANIPULATION` <=> BINARY 'INSERT' AND BINARY `EVENT_OBJECT_TABLE` <=> BINARY 'managed_payouts' AND `ACTION_ORDER`=4 AND BINARY `ACTION_STATEMENT` <=> BINARY 'BEGIN IF (NEW.record_kind=''live'' AND NOT EXISTS(SELECT 1 FROM seller_profiles s JOIN users u ON u.id=NEW.prepared_by JOIN user_roles r ON r.user_id=u.id WHERE s.id=NEW.seller_id AND s.user_id<>u.id AND u.status=''active'' AND r.role=''super_admin'' AND (NEW.approved_by IS NULL OR NEW.approved_by=u.id))) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''managed_live_payout_independent_actor_required''; END IF; END' AND BINARY `ACTION_TIMING` <=> BINARY 'BEFORE') OR (BINARY `TRIGGER_NAME` <=> BINARY 'managed_live_payout_source_cap' AND BINARY `EVENT_MANIPULATION` <=> BINARY 'INSERT' AND BINARY `EVENT_OBJECT_TABLE` <=> BINARY 'managed_payouts' AND `ACTION_ORDER`=3 AND BINARY `ACTION_STATEMENT` <=> BINARY 'BEGIN IF (NEW.record_kind=''live'' AND (NEW.amount_paisa>(COALESCE((SELECT SUM(x.amount_paisa) FROM managed_settlement_entries x JOIN managed_entitlements e ON e.id=x.entitlement_id JOIN managed_commercial_snapshots s ON s.id=e.snapshot_id WHERE e.seller_id=NEW.seller_id AND s.record_kind=''live'' AND s.live_activation_decision_id IS NOT NULL AND s.live_clearance_id IS NOT NULL AND