 IF EXISTS(SELECT 1 FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='promo_redemptions' AND CONSTRAINT_NAME='request_id' AND BINARY CHECK_CLAUSE=BINARY 'octet_length(`request_id`) between 1 and 191') THEN
  -- Approved byte-to-character correction; column type, nullability, collation and indexes are retained.
  ALTER TABLE `promo_redemptions` MODIFY COLUMN `request_id` VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL CHECK (CHAR_LENGTH(request_id) BETWEEN 1 AND 191);
 END IF;
END$$
